"""Actual P1 proposed increment: body kinematics and original constraint decomposition.
No equilibrium/strength inference from rejected linear proposals.
"""
import sys,json,shutil
import numpy as np
from scipy import sparse
from scipy.linalg import lstsq
from baseline_registry import ROOT,REPO,ref,sha,dump
from primary_ritz_storage import load as load_ritz

def main():
 assert not(ROOT/'runtime/STOP').exists();out=ROOT/'validation/integrated'/sys.argv[1];out.mkdir(exist_ok=False);shutil.copyfile(__file__,out/'producer.py');src=ROOT/'validation/integrated/primaryP1_measured_enrichment_continuation1/summary.json';s=json.loads(src.read_text());a=np.load(REPO/s['output']['path']);field=np.load(REPO/s['source_field']['path']);old=json.loads((ROOT/'validation/integrated/primaryP1_ritz_primaldual1/summary.json').read_text());ritz=load_ritz(json.loads((REPO/old['source']['path']).read_text()));x=ritz['before_x'];dx=a['proposed_x']-x;A=sparse.load_npz(REPO/old['physical_A']['path']);p=np.load(REPO/old['problem']['path']);eq=np.isfinite(p['upper'])&(p['upper']==p['lower']);sl=A@a['proposed_x']-p['lower'];leak=A@dx;body=[];force=[];reconstruction=0.
 names=['OPEN_FRAME','F0_ROOT_BACK','MOTOR_CAP','GROUND_PLATE','TEST_BASE']
 for name in names:
  X=field[name+'_points_mm'];t=field[name+'_tetra'];o=int(field[name+'_offset']);d=np.asarray(dx[o:o+3*len(X)].reshape(-1,3),dtype=float);r=np.asarray(a['physical_residual'][o:o+3*len(X)].reshape(-1,3),dtype=float);xc=X-X.mean(0);basis=np.zeros((len(X),3,6));basis[:,:,:3]=np.eye(3)
  for j in range(3):basis[:,:,3+j]=np.cross(np.eye(3)[j],xc)
  C=basis.reshape(-1,6);fit=lstsq(C,d.ravel(),cond=1e-14)[0];elastic=d-(C@fit).reshape(-1,3);edge=np.stack([X[t[:,j]]-X[t[:,0]] for j in [1,2,3]],axis=2);du=np.stack([d[t[:,j]]-d[t[:,0]] for j in [1,2,3]],axis=2);grad=du@np.linalg.inv(edge);strain=.5*(grad+grad.transpose(0,2,1));det=np.linalg.det(np.eye(3)+grad);total_field=np.asarray(field['u_mm'][o:o+3*len(X)].reshape(-1,3),dtype=float);current=X+total_field;body.append(dict(part=name,nodes=len(X),tetrahedra=len(t),maximum_node_increment_mm=float(np.max(np.linalg.norm(d,axis=1))),fitted_translation_mm=fit[:3].tolist(),fitted_small_rotation_rad=fit[3:].tolist(),maximum_nonrigid_increment_mm=float(np.max(np.linalg.norm(elastic,axis=1))),maximum_symmetric_increment_strain=float(np.max(np.linalg.norm(strain,axis=(1,2)))),minimum_increment_det=float(det.min()),maximum_increment_det=float(det.max())));force.append(dict(part=name,maximum_nodal_residual_N=float(np.max(abs(r))),net_residual_force_N=r.sum(0).tolist(),residual_moment_about_reference_centroid_Nmm=np.cross(xc,r).sum(0).tolist()));reconstruction=max(reconstruction,float(np.max(abs((C@fit).reshape(-1,3)+elastic-d))))
 mo=int(field['motor_offset']);largest=int(np.argmax(abs(dx)));ordered=np.argsort(abs(sl[eq]))[::-1];ee=np.flatnonzero(eq);eqs=[dict(row=int(ee[i]),gap_mm=float(sl[ee[i]]),increment_row_mm=float(leak[ee[i]])) for i in ordered];ii=np.flatnonzero(~eq);worst=int(ii[np.argmin(sl[ii])]);controls=dict(reconstruction_error_mm=reconstruction,reversed_residual_net_force_N=(-np.asarray(a['physical_residual'][:mo],dtype=float).reshape(-1,3).sum(0)).tolist(),omitted_gamma_value=float(dx[-1]));checks=dict(allfive_actual_bodies=len(body)==5,all2208rows=A.shape[0]==2208,actual78STEP=True,body_increment_reconstruction=reconstruction<1e-10,source_hashes=all(sha(REPO/s[k]['path'])==s[k]['SHA256'] for k in ['candidate','source_field','output']))
 cad=json.loads((REPO/s['candidate']['path']).read_text());checks['actual78STEP']=len(cad['part_references'])==78 and all(sha(REPO/v['path'])==v['SHA256'] for v in cad['part_references'].values());dump(out/'summary.json',dict(status='ACTUAL_P1_REJECTED_PRODUCT_INCREMENT_MEASURED',candidate=s['candidate'],source=ref(src),source_field=s['source_field'],checks=checks,bodies=body,body_force_residuals=force,motor_increment_translation_mm=np.asarray(dx[mo:mo+3],dtype=float).tolist(),motor_increment_rotation_rad=np.asarray(dx[mo+3:mo+6],dtype=float).tolist(),tendon_branch_increment_mm=np.asarray(dx[mo+6:-1],dtype=float).tolist(),RootY_gamma_increment_mm=float(dx[-1]),largest_mixed_coordinate_index=largest,largest_mixed_coordinate_value=float(dx[largest]),equality_gaps=eqs,worst_inequality=dict(row=worst,gap_mm=float(sl[worst])),controls=controls,physical_KKT_qualified=False,actual_support_updates=0,accepted_equilibria=0,newly_qualified_system_gate_ids=[],whole_system_release=False,limitations=['Linearized proposed increment only, never applied to actual sourcefield. Body small-rotation fit is diagnostic; strain is increment gradient, not nonlinear stress or material allowable.','Gamma/tendon generalized millimeters must be distinguished from body node displacement and motor radians. No arbitrary fixation or removal of these coordinates.','Net residual forces/moments are imbalance diagnostics, not measured support reactions.']));print(json.dumps(dict(bodies=body,gamma=float(dx[-1]),largest_index=largest,equality_gaps=eqs,worst_inequality=dict(row=worst,gap_mm=float(sl[worst])))))
if __name__=='__main__':main()
